{"explanation": "Add expired-lease reclaim to selection and guarded update while preserving atomic increment and field safety.","hypothesis": "Missing claimed-expired branch causes crash-restart/retry starvation; conditional reclaim with inclusive 60s cutoff fixes it.","source": "claimNextDue(now = new Date()): FollowUp | null {
    const timestamp = now.toISOString();
    const leaseCutoff = new Date(now.getTime() - 60000).toISOString();
    const claim = this.database.transaction(() => {
      const row = this.database
        .prepare(
          `SELECT * FROM follow_ups
           WHERE ((status IN ('scheduled', 'retrying') AND due_at <= ?) OR (status = 'claimed' AND claimed_at <= ?))
           ORDER BY due_at ASC LIMIT 1`,
        )
        .get(timestamp, leaseCutoff) as Row | undefined;
      if (!row) return null;
      const result = this.database
        .prepare(
          `UPDATE follow_ups SET status = 'claimed', claimed_at = ?, attempt_count = attempt_count + 1
           WHERE id = ? AND (((status IN ('scheduled', 'retrying')) AND due_at <= ?) OR ((status = 'claimed') AND claimed_at <= ?))`,
        )
        .run(timestamp, row.id, timestamp, leaseCutoff);
      if (result.changes !== 1) return null;
      const claimed = this.database
        .prepare("SELECT * FROM follow_ups WHERE id = ?")
        .get(row.id) as Row;
      return followUpFromRow(claimed);
    });
    return claim();
  }"}

