{"explanation":"Expired claimed leases must be reclaimable while fresh claims are protected; add lease-threshold predicate to SELECT and conditional UPDATE.","hypothesis":"Missing expired-lease branch causes crash-restart loss; unconditional status overwrite would steal live owners, so both SELECT and UPDATE need inclusive 60s lease guard.","source":"claimNextDue(now = new Date()): FollowUp | null {
    const timestamp = now.toISOString();
    const leaseThreshold = new Date(now.getTime() - 60000).toISOString();
    const claim = this.database.transaction(() => {
      const rows = this.database
        .prepare(
          `SELECT * FROM follow_ups
           WHERE ((status IN ('scheduled', 'retrying') AND due_at <= ?) OR (status = 'claimed' AND claimed_at <= ?))
           ORDER BY due_at ASC LIMIT 10`,
        )
        .all(timestamp, leaseThreshold) as Row[];
      for (const row of rows) {
        const result = this.database
          .prepare(
            `UPDATE follow_ups SET status = 'claimed', claimed_at = ?, attempt_count = attempt_count + 1
             WHERE id = ? AND ((status IN ('scheduled', 'retrying') AND due_at <= ?) OR (status = 'claimed' AND claimed_at <= ?))`,
          )
          .run(timestamp, row.id, timestamp, leaseThreshold);
        if (result.changes !== 1) continue;
        const claimed = this.database
          .prepare("SELECT * FROM follow_ups WHERE id = ?")
          .get(row.id) as Row;
        return followUpFromRow(claimed);
      }
      return null;
    });
    return claim();
  }"}

